14	  constructor(private readonly responses: Array<string | Error>) {}
15	  async complete(messages: ChatMessage[], options?: CompleteOptions): Promise<string> {
16	    this.calls.push({ messages, options });
17	    const next = this.responses.shift();
18	    if (next === undefined) throw new Error("StubAdapter exhausted");
19	    if (next instanceof Error) throw next;
20	    return next;
21	  }
22	}
