28	suite("segmenter.segment", () => {
29	  beforeEach(() => clearPromptCache());
30	
31	  test("returns validated segments on first-try success", async () => {
32	    const doc = await openDoc("line1\nline2\nline3\nline4\nline5\n");
33	    const adapter = new StubAdapter([JSON.stringify({
34	      segments: [
35	        { label: "Header", oneLiner: "first block", startLine: 1, endLine: 3, difficulty: "trivial" },
36	        { label: "Body",   oneLiner: "second block", startLine: 4, endLine: 5, difficulty: "standard" },
37	      ],
38	    })]);
39	    const result = await segment(doc, { adapter, promptsDir: FIXTURES_DIR });
40	    assert.strictEqual(result.length, 2);
41	    assert.strictEqual(result[0].id, "seg-0");
42	    assert.strictEqual(result[0].label, "Header");
43	    assert.strictEqual(result[0].difficulty, "trivial");
44	    assert.strictEqual(result[1].id, "seg-1");
45	    assert.ok(result[0].code.length > 0);
46	  });
47	
48	  test("retries on malformed JSON and succeeds", async () => {
49	    const doc = await openDoc("a\nb\nc\n");
50	    const adapter = new StubAdapter([
51	      "not json at all",
52	      JSON.stringify({ segments: [{ label: "X", oneLiner: "y", startLine: 1, endLine: 2, difficulty: "standard" }] }),
53	    ]);
54	    const result = await segment(doc, { adapter, promptsDir: FIXTURES_DIR });
55	    assert.strictEqual(adapter.calls.length, 2);
56	    assert.strictEqual(result.length, 1);
57	    const retrySystemMsg = adapter.calls[1].messages.find(m => m.role === "system")?.content ?? "";
58	    assert.ok(retrySystemMsg.includes("CRITICAL"), "retry should include stricter instruction");
59	  });
