1	import * as vscode from "vscode";
2	import { createHash } from "node:crypto";
3	import type { Segment, Difficulty } from "../types";
4	import type { ChatMessage, LLMAdapter } from "../llm/adapter";
5	import { CancelledError, MalformedResponseError } from "../llm/adapter";
6	import { loadPrompt } from "../prompts/loader";
7	
8	const VALID_DIFFICULTIES = new Set<Difficulty>(["trivial", "standard", "complex", "critical"]);
9	
10	export const DEFAULT_MAX_LINES = 2000;
11	export const MIN_COVERAGE_RATIO = 0.7;
12	
13	export class FileTooLargeError extends Error {
14	  constructor(
15	    public readonly lineCount: number,
16	    public readonly maxLines: number,
17	  ) {
18	    super(
19	      `File has ${lineCount} lines; CodeWalk currently supports files up to ${maxLines} lines.`,
20	    );
21	    this.name = "FileTooLargeError";
22	  }
23	}
24	
25	export type SegmenterLogger = (message: string) => void;
26	
27	export interface SegmenterDeps {
28	  adapter: LLMAdapter;
29	  promptsDir: string;
30	  maxLines?: number;
31	  logger?: SegmenterLogger;
32	  token?: vscode.CancellationToken;
33	}
34	
35	interface RawSegment {
36	  label?: unknown;
37	  oneLiner?: unknown;
38	  startLine?: unknown;
39	  endLine?: unknown;
40	  difficulty?: unknown;
41	}
42	
43	interface ValidatedSegment {
44	  label: string;
45	  oneLiner: string;
46	  startLine: number;
47	  endLine: number;
48	  difficulty: Difficulty;
49	}
50	
51	interface ParseResult {
52	  segments: ValidatedSegment[];
53	  droppedCount: number;
54	}
55	
56	class ValidationFailure extends Error {}
57	
58	export async function segment(
59	  document: vscode.TextDocument,
60	  deps: SegmenterDeps,
61	): Promise<Segment[]> {
62	  const maxLines = deps.maxLines ?? DEFAULT_MAX_LINES;
63	  if (document.lineCount > maxLines) {
64	    throw new FileTooLargeError(document.lineCount, maxLines);
65	  }
66	
67	  const log = deps.logger ?? noop;
68	  const signal = toAbortSignal(deps.token);
69	  throwIfCancelled(deps.token);
70	
71	  const numberedCode = numberLines(document.getText());
72	  const systemPrompt = loadPrompt(
73	    "segmentation",
74	    {
75	      language: document.languageId,
76	      filename: document.fileName,
77	      code: numberedCode,
78	    },
79	    deps.promptsDir,
80	  );
81	
82	  const baseMessages: ChatMessage[] = [{ role: "system", content: systemPrompt }];
83	
84	  let firstRaw: string | undefined;
85	  let firstFailureReason: string | undefined;
86	  try {
87	    firstRaw = await deps.adapter.complete(baseMessages, {
88	      responseFormat: "json_object",
89	      signal,
90	    });
91	    return finalize(parseAndValidate(firstRaw, document), document, log);
92	  } catch (firstError) {
93	    if (firstError instanceof CancelledError) throw firstError;
94	    if (firstError instanceof ValidationFailure) {
95	      firstFailureReason = firstError.message;
96	    } else if (firstError instanceof MalformedResponseError) {
97	      firstFailureReason = "response was not valid JSON";
98	    } else {
99	      throw firstError;
100	    }
101	
102	    throwIfCancelled(deps.token);
103	
104	    const retrySystem =
105	      systemPrompt +
106	      `\n\nCRITICAL: your previous response failed validation: ${firstFailureReason}. Respond with ONLY the raw JSON object matching the schema — no markdown fences, no commentary, no explanation. Begin with { and end with }.`;
107	    const retryMessages: ChatMessage[] = [{ role: "system", content: retrySystem }];
108	
109	    let secondRaw: string | undefined;
110	    try {
111	      secondRaw = await deps.adapter.complete(retryMessages, {
112	        responseFormat: "json_object",
113	        signal,
114	      });
115	      return finalize(parseAndValidate(secondRaw, document), document, log);
116	    } catch (secondError) {
117	      if (secondError instanceof CancelledError) throw secondError;
118	      throw new MalformedResponseError(
119	        `LLM did not return valid segment JSON after retry. First failure: ${firstFailureReason}. Second failure: ${(secondError as Error).message ?? String(secondError)}`,
120	        JSON.stringify({ first: firstRaw, second: secondRaw ?? "<no response>" }),
121	      );
122	    }
123	  }
124	}
125	
126	function toAbortSignal(token?: vscode.CancellationToken): AbortSignal | undefined {
127	  if (!token) return undefined;
128	  const controller = new AbortController();
129	  if (token.isCancellationRequested) controller.abort();
130	  else token.onCancellationRequested(() => controller.abort());
131	  return controller.signal;
132	}
133	
134	function throwIfCancelled(token?: vscode.CancellationToken): void {
135	  if (token?.isCancellationRequested) throw new CancelledError();
136	}
137	
138	function numberLines(text: string): string {
139	  return text.split("\n").map((line, i) => `${i + 1}: ${line}`).join("\n");
140	}
141	
142	function parseAndValidate(raw: string, document: vscode.TextDocument): ParseResult {
143	  let parsed: unknown;
144	  try {
145	    parsed = JSON.parse(raw);
146	  } catch {
147	    throw new ValidationFailure("response is not valid JSON");
148	  }
149	  if (
150	    !parsed ||
151	    typeof parsed !== "object" ||
152	    !Array.isArray((parsed as { segments?: unknown }).segments)
153	  ) {
154	    throw new ValidationFailure("response does not contain a 'segments' array");
155	  }
156	
157	  const rawSegments = (parsed as { segments: RawSegment[] }).segments;
158	  const lineCount = document.lineCount;
159	  const validated: ValidatedSegment[] = [];
160	  let droppedCount = 0;
161	
162	  for (const r of rawSegments) {
163	    const startLine = Number(r.startLine);
164	    let endLine = Number(r.endLine);
165	    const label = typeof r.label === "string" ? r.label.trim() : "";
166	    const oneLiner = typeof r.oneLiner === "string" ? r.oneLiner.trim() : "";
167	    const difficulty = typeof r.difficulty === "string" ? r.difficulty : "";
168	
169	    if (!Number.isInteger(startLine) || startLine < 1) { droppedCount++; continue; }
170	    if (!Number.isInteger(endLine)) { droppedCount++; continue; }
171	    if (endLine > lineCount) endLine = lineCount;
172	    if (endLine < startLine) { droppedCount++; continue; }
173	    if (label.length === 0 || oneLiner.length === 0) { droppedCount++; continue; }
174	    if (!VALID_DIFFICULTIES.has(difficulty as Difficulty)) { droppedCount++; continue; }
175	
176	    validated.push({ label, oneLiner, startLine, endLine, difficulty: difficulty as Difficulty });
177	  }
178	
179	  if (validated.length === 0) {
180	    throw new ValidationFailure("no segments passed per-field validation");
181	  }
182	
183	  validated.sort((a, b) => a.startLine - b.startLine || a.endLine - b.endLine);
184	
185	  for (let i = 1; i < validated.length; i++) {
186	    const prev = validated[i - 1];
187	    const curr = validated[i];
188	    if (curr.startLine <= prev.endLine) {
189	      throw new ValidationFailure(
190	        `segments overlap: "${prev.label}" (lines ${prev.startLine}-${prev.endLine}) and "${curr.label}" (lines ${curr.startLine}-${curr.endLine})`,
191	      );
192	    }
193	  }
194	
195	  return { segments: validated, droppedCount };
196	}
197	
198	function finalize(
199	  parsed: ParseResult,
200	  document: vscode.TextDocument,
201	  log: SegmenterLogger,
202	): Segment[] {
203	  const { segments, droppedCount } = parsed;
204	  const lineCount = document.lineCount;
205	
206	  const finalized: Segment[] = segments.map((s) => {
207	    const range = new vscode.Range(
208	      s.startLine - 1,
209	      0,
210	      Math.min(s.endLine, lineCount) - 1,
211	      Number.MAX_SAFE_INTEGER,
212	    );
213	    const code = document.getText(range);
214	    return {
215	      id: computeSegmentId(s.label, s.startLine, s.endLine, code),
216	      label: s.label,
217	      oneLiner: s.oneLiner,
218	      startLine: s.startLine,
219	      endLine: s.endLine,
220	      code,
221	      difficulty: s.difficulty,
222	    };
223	  });
224	
225	  const coverage = computeCoverage(finalized, document);
226	  log(
227	    `[segmenter] ${finalized.length} segment(s), coverage ${(coverage * 100).toFixed(0)}%` +

