1	import * as vscode from "vscode";
2	import { readUserConfig } from "../utils/config";
3	import { resolveBackend } from "../llm/presets";
4	import { OpenAICompatibleAdapter } from "../llm/openAiCompatibleAdapter";
5	import { isOllamaReachable } from "../llm/ollamaDetection";
6	import { FileTooLargeError, segment } from "../engine/segmenter";
7	import type { SegmentStore } from "../engine/segmentStore";
8	import {
9	  AuthError,
10	  CancelledError,
11	  MalformedResponseError,
12	  NetworkError,
13	  RateLimitError,
14	} from "../llm/adapter";
15	import { runFirstRunWizard } from "./firstRunWizard";
16	
17	export function registerStartWalkthrough(
18	  context: vscode.ExtensionContext,
19	  store: SegmentStore,
20	  output: vscode.OutputChannel,
21	): vscode.Disposable {
22	  return vscode.commands.registerCommand("codewalk.startWalkthrough", async () => {
23	    const editor = vscode.window.activeTextEditor;
24	    if (!editor) {
25	      vscode.window.showInformationMessage("Open a file first to start CodeWalk.");
26	      return;
27	    }
28	    const document = editor.document;
29	    if (document.getText().trim().length === 0) {
30	      vscode.window.showInformationMessage("This file is empty — nothing to walk through.");
31	      return;
32	    }
33	
34	    const userConfig = readUserConfig();
35	    let resolved;
36	    try {
37	      resolved = resolveBackend(userConfig);
38	    } catch (e) {
39	      showSettingsError(`CodeWalk config error: ${(e as Error).message}`);
40	      return;
41	    }
42	
43	    let finalResolved = resolved;
44	    const ollamaNotReady =
45	      resolved.backend === "ollama-local" && !(await isOllamaReachable(resolved.baseUrl));
46	    const cloudKeyMissing =
47	      resolved.backend !== "ollama-local" && resolved.requiresApiKey && !resolved.apiKey;
48	
49	    if (ollamaNotReady || cloudKeyMissing) {
50	      const wizardResult = await runFirstRunWizard();
51	      if (!wizardResult) return; // user cancelled the wizard
52	      finalResolved = wizardResult;
53	      if (
54	        finalResolved.backend === "ollama-local" &&
55	        !(await isOllamaReachable(finalResolved.baseUrl))
56	      ) {
57	        vscode.window.showErrorMessage(
58	          `CodeWalk can't reach Ollama at ${finalResolved.baseUrl}. Start Ollama and try again.`,
59	        );
60	        return;
61	      }
62	    }
63	
64	    store.clear(document.uri);
65	
66	    const adapter = new OpenAICompatibleAdapter({
67	      baseUrl: finalResolved.baseUrl,
68	      apiKey: finalResolved.apiKey,
69	      model: finalResolved.model,
70	    });
71	
72	    await vscode.window.withProgress(
73	      {
74	        location: vscode.ProgressLocation.Notification,
75	        title: "CodeWalk: Analyzing…",
76	        cancellable: true,
77	      },
78	      async (_progress, token) => {
79	        try {
80	          const promptsDir = context.asAbsolutePath("prompts");
81	          const segments = await segment(document, {
82	            adapter,
83	            promptsDir,
84	            logger: (msg) => output.appendLine(msg),
85	            token,
86	          });
87	          store.set(document.uri, segments);
88	          output.appendLine(`[success] ${segments.length} segments for ${document.fileName}`);
89	        } catch (e) {
90	          handleError(e, output);
91	        }
92	      },
93	    );
94	  });
95	}
96	
97	function showSettingsError(message: string): void {
98	  vscode.window
99	    .showErrorMessage(message, "Open Settings")
100	    .then((action) => {
101	      if (action === "Open Settings") {
102	        vscode.commands.executeCommand("workbench.action.openSettings", "codewalk");
103	      }
104	    });
105	}
106	
107	function handleError(e: unknown, output: vscode.OutputChannel): void {
108	  if (e instanceof CancelledError) {
109	    output.appendLine("[cancelled] user cancelled CodeWalk analysis");
110	    return;
111	  }
112	  if (e instanceof NetworkError) {
113	    output.appendLine(`[NetworkError] ${e.message}`);
114	    vscode.window.showErrorMessage(
115	      "CodeWalk couldn't reach the LLM. Check your connection and backend URL.",
116	    );
117	  } else if (e instanceof AuthError) {
118	    output.appendLine(`[AuthError] ${e.message}`);
119	    showSettingsError("CodeWalk's API key was rejected. Open settings to update it.");
120	  } else if (e instanceof RateLimitError) {
121	    output.appendLine(`[RateLimitError] ${e.message}${e.retryAfter ? ` retry-after: ${e.retryAfter}s` : ""}`);
122	    vscode.window.showErrorMessage("CodeWalk hit a rate limit. Try again in a moment.");
123	  } else if (e instanceof MalformedResponseError) {
124	    output.appendLine(`[MalformedResponseError] ${e.message}\nRaw: ${e.rawResponse ?? "<none>"}`);
125	    showSettingsError(
126	      "CodeWalk couldn't parse the model's response. Try a more capable model in settings.",
127	    );
128	  } else if (e instanceof FileTooLargeError) {
129	    output.appendLine(`[FileTooLargeError] ${e.message}`);
130	    vscode.window.showWarningMessage(
131	      `CodeWalk can't analyze files over ${e.maxLines} lines yet. This file has ${e.lineCount}.`,
132	    );
133	  } else {
134	    const err = e as Error;
135	    output.appendLine(`[Unhandled] ${err.stack ?? err.message ?? String(e)}`);
136	    vscode.window.showErrorMessage(
137	      "CodeWalk encountered an unexpected error. See the Output panel.",
138	    );
139	  }
140	}

